import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { add_remove_member_dashboard } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    memberaddition: Boolean
  },
  mixins: [get_all_org_users],
  data() {
    return {
      selectTeam: "",
      loading: false,
      searchF: "",
      userArray: []
    };
  },
  watch: {
    memberaddition: {
      async handler() {
        this.$store.commit("Setnamesearch", "");
        await this.get_all_org_users();
        await this.fetch_details();
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.selectTeam = "";
      this.$refs.form.resetValidation();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        await this.grant_admin_access();
      }
    },
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
    },
    async grant_admin_access() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_remove_member_dashboard, {
          input: {
            dashboard_id: this.$store.getters.GetdashboardDetails.dashboard_id,
            user_id: this.selectTeam,
            organization_id: data.organization.organization_id,
            action_type: "ADD"
          }
        }));
        this.loading = false;
        // console.log(result);
        var response = JSON.parse(result.data.add_remove_member_dashboard);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("updaterefesh", "data");
          this.selectTeam = "";
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
